async function* rolls() {
  yield 4;
  yield 6;
}

async function main() {
  const doubled = await Array.fromAsync(rolls(), (n) => n * 2);
  console.log(doubled.join(","));

  const mixed = await Array.fromAsync([Promise.resolve("a"), "b"]);
  console.log(mixed.join(","));

  console.log(Array.from(rolls()).length);
}

main();
console.log("rolling");
